def fit(grid,maxp=10):
 data=[(r,c,grid[r][c]) for r in range(3,len(grid)) for c in range(3,len(grid[0])) if grid[r][c]!=0]
 cand=[]
 for p in range(1,maxp+1):
  for a in range(p):
   bins=[Counter() for _ in range(p)]
   for r,c,v in data: bins[(c+a*r)%p][v]+=1
