def transform(grid):
    out = [row[:] for row in grid]
    height, width = len(grid), len(grid[0])

    samples = [(r + c, grid[r][c])
               for r in range(3, height)
               for c in range(3, width)
               if grid[r][c] != 0]
    best = None
    for period in range(1, 11):
        bins = [Counter() for _ in range(period)]
        for phase, color in samples:
            bins[phase % period][color] += 1
        score = sum(max(counts.values()) for counts in bins if counts)
        candidate = (score, -period, [counts.most_common(1)[0][0] if counts else 0
                                       for counts in bins])
        if best is None or candidate[:2] > best[:2]:
            best = candidate

    colors = best[2]
    for r in range(height):
        for c in range(width):
            if out[r][c] != 0:
                continue
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                out[r][c] = colors[(r + c) % len(colors)]
    return out
